def is_match(s, p):
    memo = {}
    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if j == len(p):
            res = i == len(s)
            memo[(i, j)] = res
            return res
        if j + 1 < len(p) and p[j + 1] == '*':
            # zero occurrences: skip the star and its preceding char
            if dp(i, j + 2):
                memo[(i, j)] = True
                return True
            # one or more occurrences: if current char matches
            if i < len(s) and (s[i] == p[j] or p[j] == '.'):
                if dp(i + 1, j):
                    memo[(i, j)] = True
                    return True
            memo[(i, j)] = False
            return False
        else:
            # single character match
            if i < len(s) and (s[i] == p[j] or p[j] == '.'):
                res = dp(i + 1, j + 1)
                memo[(i, j)] = res
                return res
            memo[(i, j)] = False
            return False
    return dp(0, 0)
```
